const r = $input.first().json;
const body = r.body || {};
if (!Array.isArray(body.keys)) throw new Error('No keys array: status ' + r.statusCode);
const locs = $('Params').first().json.locales;
const norm = s => String(s || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
const pick = v => { if (v && typeof v === 'object') return v.other || Object.values(v)[0] || ''; try { const o = JSON.parse(v); if (o && typeof o === 'object') return o.other || Object.values(o)[0] || ''; } catch (e) {} return v; };
const matches = {}; const en_values = [];
for (const k of body.keys) {
  if (k.is_archived) continue;
  const tr = {}; let en = null;
  for (const t of (k.translations || [])) { const iso = (t.language_iso || '').toLowerCase(); const v = pick(t.translation); if (iso === 'en') en = v; else if (locs.includes(iso) && v && String(v).trim()) tr[iso] = v; }
  const name = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
  const e = norm(en); if (!e) continue;
  en_values.push(e);
  if (!matches[e]) matches[e] = { key: name, plural: !!k.is_plural, t: tr };
}
return [{ json: { status: r.statusCode, pages: (r.headers || {})['x-pagination-page-count'], total: (r.headers || {})['x-pagination-total-count'], keys: body.keys.length, en_values, matches } }];
